    /// <summary>
    /// DMF Error Telemetry
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">e</param>
    [DataEventHandler(tableStr(DMFDefinitionGroupExecution), DataEventType::Updated)]
    public static void DMFDefinitionGroupExecution_onUpdated(Common sender, DataEventArgs e)
    {
        DMFDefinitionGroupExecution dMFDefinitionGroupExecution = sender;
        notes eventName, DMFerror;
        boolean isError = false;
        
        eventName = "@MET:EvntNme";
        if (dMFDefinitionGroupExecution.StagingStatus == DMFBatchJobStatus::Error)
        {
            DMFerror = "@MET:DErr";
            isError = true;
        }
        else if (dMFDefinitionGroupExecution.TargetStatus == DMFBatchJobStatus::Error)
        {
            str errorMessage = "@DMF:StagingToTargetImportFailed";
            DMFerror = "@MET:METError" + ' ' + strFmt("@DMF:EntityImportError", dMFDefinitionGroupExecution.Entity, errorMessage);
            isError = true;
        }

        if (isError || dMFDefinitionGroupExecution.TargetErrorCount > 0)
        {
            /*
            Map customProperties = new Map(Types::String, Types::String);
            customProperties.insert("@MET:DMExctnGrp", dMFDefinitionGroupExecution.DefinitionGroup);
            customProperties.insert("@MET:DeftnEntNme", dMFDefinitionGroupExecution.Entity);
            customProperties.insert("@MET:ExctnLglEntty", dMFDefinitionGroupExecution.Company);
            customProperties.insert("@MET:ExuctnId", dMFDefinitionGroupExecution.ExecutionId);
            customProperties.insert("@MET:StagngErrCnt", int2Str(dMFDefinitionGroupExecution.StagingErrorCount));
            customProperties.insert("@MET:Stngnstus", enum2Str(dMFDefinitionGroupExecution.StagingStatus));
            customProperties.insert("@MET:DTrgtErrCnt", int2Str(dMFDefinitionGroupExecution.TargetErrorCount));
            customProperties.insert("@MET:TrgtStus", enum2Str(dMFDefinitionGroupExecution.TargetStatus));
            customProperties.insert("@MET:ClStck", METSysGlobalTelemetry::formatXppCallStack(xSession::xppCallStack()));
            // CS CB718 VM 28032024-DMFLoggingAppinsights
            */
            //Based on the flags the primary key detail will be added in the error

            // CB718 VM Task - 162235 Replace logging with new format start
            //METTelemetryDMFLogging metTelemetryDMFLogging =  new METTelemetryDMFLogging(dMFDefinitionGroupExecution,DMFerror);
            METTelemetryDMFLogging metTelemetryDMFLogging = METTelemetryDMFLogging::construct(dMFDefinitionGroupExecution,DMFerror);
            if(DMFEntity::find(dMFDefinitionGroupExecution.Entity).METIncludeErrorLogging && SysIntParameters::find().METEntityLogging)
            {
                DMFerror += METSysGlobalTelemetry::getPrimaryKeyDetails(dMFDefinitionGroupExecution,metTelemetryDMFLogging);
            }

            metTelemetryDMFLogging.error = DMFerror;
            metTelemetryDMFLogging.processEvent(eventName);
            // CB718 VM Task - end

            //customProperties.insert("@MET:ExcptnMssg", DMFerror);
            
           // SysGlobalTelemetry::logEventWithCustomProperties(eventName, customProperties);

            /* Commented and can be used in case we go with DXC 
            DXCInsightsLogEvents::logEvent(
                  DXCInsightsLogEventContract::newFromTypeAndName(
                      DXCInsightsLoggingType::LogCustom, "Custom DXC Journal Err", customProperties));
            */ 
        }
    }

    public static str formatXppCallStack(container _xppCallStack)
    {
        str result = '';

        // Each stack frame is four elements [Method, Line Number, Model Publisher, Model]
        for (int i = 1; i <= conLen(_xppCallStack); i += 4)
        {
            str methodName = conPeek(_xppCallStack, i);
            str lineNum = conPeek(_xppCallStack, i + 1);
            str publisher = conPeek(_xppCallStack, i + 2);
            str model = conPeek(_xppCallStack, i + 3);

            // Add a newline between stack frames
            if (i > 1)
            {
                result += '\n at';
            }
            
            // Model identifer
            if (publisher || model)
            {
                result += strFmt('[%1%2%3]', publisher, (publisher && model ? ':' : ''), model);
            }
            
            // Code
            result += strFmt('%1%2', methodName, (lineNum && lineNum != '0' ? ':' + lineNum : ''));
        }

        return result;
    }

    /// <summary>
    /// CB718 VM 28032024-DMFLoggingAppinsights
    /// Find the primary key and update the error message
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">_dmfDefinitionGroupExecution</param>
    /// <param name = "_metTelemetryDMFLogging">_metTelemetryDMFLogging</param>
    /// <returns>DMFErrorMessage</returns>
    public static DMFErrorMessage getPrimaryKeyDetails(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution,METTelemetryDMFLogging _metTelemetryDMFLogging)
    {
        SysDictIndex keyIndex;
        DMFStagingValidationLog DMFStagingValidationLog;
        DictField dictField;
        int fieldIndex;
        SysDictTable sysDictTable;
        Common buffer;
        SysDictTable dictTable;
        Notes dmfError;

        while select * from DMFStagingValidationLog
                where DMFStagingValidationLog.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
        {
            TableName tablename = DMFStagingValidationLog.StagingTableName;
            dmfError = '';
            sysDictTable = new SysDictTable(tablename2id(tablename));
            if (sysDictTable)
            {
                TableId tableId = sysDictTable.id();
                dictTable = new SysDictTable(tableId);
                str fieldidPrim;
                int counter,fieldId;
                
                keyIndex = new SysDictIndex(tableId, sysDictTable.primaryIndex());
                
                if (keyIndex)
                {
                    for (fieldIndex = 1; fieldIndex <= keyIndex.numberOfFields(); fieldIndex++)
                    {
                        dictField = new DictField(tableId, keyindex.field(fieldindex));
                        buffer = dictTable.makeRecord();
                        fieldidPrim = fieldId2Name(tableId, dictfield.id());

                        select firstonly buffer
                            where buffer.RecId == DMFStagingValidationLog.StagingRecId;

                        if (fieldidPrim != METConstants::DefinitionGroup && fieldidPrim != METConstants::ExecutionId)
                        {
                            dmfError += strFmt(METConstants::TwoStrFmt,dictfield.label(),buffer.(dictfield.id()));
                        }
                    }
                    dmfError += DMFStagingValidationLog.ErrorMessage;
                }

                DictFieldGroup dictFieldGrp = new DictFieldGroup(tableId,METConstants::METReference);
               // If table is having table group METReference then check all the fields and assign those fields as custom dimensions
                if (dictFieldGrp)
                {
                    //Map customProperties = new Map(Types::String, Types::String);

                    for (counter = 1; counter <= dictFieldGrp.numberOfFields(); counter++)
                    {
                        fieldId = dictFieldGrp.field(counter); 

                        dictField = new DictField(tableId, fieldId);
                        if (buffer.(fieldId))
                        {
                            dmfError += strFmt("@MET:Multiplestrmt",dictField.label(),any2str(buffer.(fieldId)));
                            //Reference Added as custom dimension
                           // customProperties.insert(dictField.label(),any2str(buffer.(fieldId)));
                            _metTelemetryDMFLogging.addRuntimeProperty(dictField.label(),any2str(buffer.(fieldId)));
                        }
                    }//for

                    // CB718 VM Task - 162235 Replace logging with new format hence commenting below code.
                    /*
                    customProperties.insert("@MET:DeftnEntNme", DMFStagingValidationLog.EntityName);
                    customProperties.insert("@MET:ExcptnMssg", DMFerror);
                    customProperties.insert("@MET:ExctnLglEntty", DMFStagingValidationLog.company());
                    customProperties.insert("@MET:ExuctnId", DMFStagingValidationLog.ExecutionId);
                    customProperties.insert("@MET:ClStck", METSysGlobalTelemetry::formatXppCallStack(xSession::xppCallStack()));
                    customProperties.insert("@MET:EvntNme", DMFerror);
                   
                    SysGlobalTelemetry::logEventWithCustomProperties(METConstants::METDMFError, customProperties);
                    */

                    /*
                    DXCInsightsLogEvents::logEvent(
                    DXCInsightsLogEventContract::newFromTypeAndName(
                        DXCInsightsLoggingType::LogCustom, "Metcash DXC DMF Error", customProperties)); */
                }
            }
        }
        return dmfError;
    }
